package com.fsrs.server.dto.study;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * Body of {@code POST /api/study/review}.
 *
 * @param cardId         card being graded
 * @param rating         1 Again, 2 Hard, 3 Good, 4 Easy - the FSRS grade
 * @param durationMs     how long the learner took; stored for the optimizer and analytics
 * @param clientReviewId idempotency key generated by the client <em>before</em> the request.
 *                       Required, because idempotency that the client may skip is not
 *                       idempotency - a retry without a key is indistinguishable from a
 *                       second genuine review.
 */
public record ReviewRequest(
        @NotNull Long cardId,
        @NotNull @Min(1) @Max(4) Integer rating,
        @Min(0) Integer durationMs,
        @NotBlank @Size(max = 64) String clientReviewId) {
}
